// Program.cs
builder.Services.AddResponseCaching(options =>
{
    options.MaximumBodySize = 64 * 1024; // 64 KB
    options.UseCaseSensitivePaths = false;
});

builder.Services.AddOptions<ResponseCacheOptions>()
    .Configure<IConfiguration>((options, config) =>
    {
        options.DefaultExpiration = TimeSpan.FromSeconds(30);
    });

var app = builder.Build();
app.UseResponseCaching(); // Before routing / auth

// In a controller or minimal API
[ResponseCache(CacheProfileName = "StaticProducts")]
[HttpGet("api/products")]
public async Task<IActionResult> GetProducts()
{
    var products = await _service.GetAllAsync();
    return Ok(products);
}

// In Program.cs configuration
builder.Services.AddControllersWithViews(options =>
{
    options.CacheProfileNames.Add("StaticProducts", new CacheProfile
    {
        Duration = "60",
        Location = ResponseCacheLocation.Any,
        VaryByHeader = "Accept-Encoding",
        NoStore = false
    });
});

[ResponseCache(VaryByQueryKeys = new[] { "search", "category" }, Duration = 120)]
[HttpGet("api/products")]
public async Task<IActionResult> SearchProducts(
    [FromQuery] string? search,
    [FromQuery] string? category)
{
    var results = await _service.SearchAsync(search, category);
    return Ok(results);
}
// GET /api/products?search=laptop&category=electronics
// => cached separately from ?search=phone&category=electronics
